if (!validator(input)) {
  const messages = (validator.errors ?? []).map((err: ErrorObject) => {
    const rawPath = (err as any).instancePath ?? (err as any).dataPath ?? '';
    const normalizedPath = rawPath.replace(/^\//, '');
    const path = normalizedPath.replace(/\//g, '.') || 'input';

    if (err.keyword === 'required' && 'missingProperty' in err.params) {
      return `Property ${err.params.missingProperty} is required`;
